import { describe, expect, it } from 'vitest'
import type { Appointment, RawAppointment } from '@/types'
import { bySortIndex, toAppointment } from '@/api/appointments'

const toNaiveIso = (year: number, month: number, day: number, hours = 0, minutes = 0) => {
  const pad = (n: number) => String(n).padStart(2, '0')
  const date = `${year}-${pad(month)}-${pad(day)}`
  return hours === 0 && minutes === 0 ? date : `${date}T${pad(hours)}:${pad(minutes)}:00`
}

const raw = (fields: Partial<RawAppointment>): RawAppointment => ({
  sort_index: 0,
  ...fields,
})

describe('toAppointment', () => {
  describe('date-only variant (start_date / end_date)', () => {
    it('passes start_date / end_date through as startDateISO / endDateISO', () => {
      const result = toAppointment(raw({ start_date: '2024-01-15', end_date: '2024-01-18' }))
      expect(result.startDateISO).toBe('2024-01-15')
      expect(result.endDateISO).toBe('2024-01-18')
    })

    it('formats date and time for a single-day all-day appointment', () => {
      const result = toAppointment(
        raw({ start_date: '2024-01-15', end_date: '2024-01-15', title: 'Jahreshauptversammlung' }),
      )
      expect(result.date).toBe('Mo., 15. Jan. 2024')
      expect(result.time).toBe('ganztägig')
      expect(result.title).toBe('Jahreshauptversammlung')
    })

    it('formats a multi-day span', () => {
      const result = toAppointment(raw({ start_date: '2024-01-15', end_date: '2024-01-18' }))
      expect(result.date).toBe('Mo., 15. Jan. 2024 - Do., 18. Jan. 2024')
      expect(result.time).toBe('ganztägig')
    })
  })

  describe('datetime variant (start_date_time / end_date_time)', () => {
    it('passes start_date_time / end_date_time through as startDateISO / endDateISO', () => {
      const result = toAppointment(
        raw({
          start_date_time: toNaiveIso(2024, 1, 15, 14, 30),
          end_date_time: toNaiveIso(2024, 1, 15, 16, 45),
        }),
      )
      expect(result.startDateISO).toBe(toNaiveIso(2024, 1, 15, 14, 30))
      expect(result.endDateISO).toBe(toNaiveIso(2024, 1, 15, 16, 45))
    })

    it('formats same-calendar-day datetime range', () => {
      const result = toAppointment(
        raw({
          start_date_time: toNaiveIso(2024, 1, 15, 14, 30),
          end_date_time: toNaiveIso(2024, 1, 15, 16, 45),
          title: 'Vorstandssitzung',
        }),
      )
      expect(result.date).toBe('Mon, 15. Jan 2024')
      expect(result.time).toBe('14:30 - 16:45 Uhr')
      expect(result.title).toBe('Vorstandssitzung')
    })

    it('1-minute difference collapses date span to a single day (tracer branch)', () => {
      const result = toAppointment(
        raw({
          start_date_time: toNaiveIso(2024, 1, 15, 14, 30),
          end_date_time: toNaiveIso(2024, 1, 15, 14, 31),
        }),
      )
      expect(result.date).toBe('Mon, 15. Jan 2024')
      expect(result.time).toBe('14:30 - 14:31 Uhr')
    })

    it('cross-midnight datetime span renders both endpoints', () => {
      const result = toAppointment(
        raw({
          start_date_time: toNaiveIso(2024, 1, 15, 23, 30),
          end_date_time: toNaiveIso(2024, 1, 16, 0, 30),
        }),
      )
      expect(result.date).toBe('Mon, 15. Jan 2024 - Tue, 16. Jan 2024')
      expect(result.time).toBe('23:30 - 0:30 Uhr')
    })
  })

  describe('ISO passthrough priority (datetime beats date)', () => {
    it('uses start_date_time over start_date when both are present', () => {
      const result = toAppointment(
        raw({
          start_date: '2024-01-15',
          end_date: '2024-01-15',
          start_date_time: toNaiveIso(2024, 1, 15, 14, 30),
          end_date_time: toNaiveIso(2024, 1, 15, 16, 45),
        }),
      )
      expect(result.startDateISO).toBe(toNaiveIso(2024, 1, 15, 14, 30))
      expect(result.endDateISO).toBe(toNaiveIso(2024, 1, 15, 16, 45))
    })

    it('falls back to start_date when datetime fields are absent', () => {
      const result = toAppointment(raw({ start_date: '2024-01-15', end_date: '2024-01-18' }))
      expect(result.startDateISO).toBe('2024-01-15')
      expect(result.endDateISO).toBe('2024-01-18')
    })

    it('throws when neither date nor datetime range is present (date/time formatters run first)', () => {
      expect(() => toAppointment(raw({ title: 'Lost' }))).toThrow(
        'Appointment has no start or end date',
      )
    })
  })

  describe('field pass-through and fallbacks', () => {
    it('defaults title to "-" when title is missing', () => {
      expect(toAppointment(raw({ start_date: '2024-01-15', end_date: '2024-01-15' })).title).toBe(
        '-',
      )
    })

    it('defaults title to "-" when title is the empty string', () => {
      expect(
        toAppointment(raw({ start_date: '2024-01-15', end_date: '2024-01-15', title: '' })).title,
      ).toBe('-')
    })

    it('passes description through when present', () => {
      expect(
        toAppointment(
          raw({
            start_date: '2024-01-15',
            end_date: '2024-01-15',
            description: 'Treffen im Clubhaus',
          }),
        ).description,
      ).toBe('Treffen im Clubhaus')
    })

    it('passes link through when present', () => {
      expect(
        toAppointment(
          raw({
            start_date: '2024-01-15',
            end_date: '2024-01-15',
            link: 'https://example.org/event',
          }),
        ).link,
      ).toBe('https://example.org/event')
    })

    it('leaves description and link undefined when absent', () => {
      const result = toAppointment(raw({ start_date: '2024-01-15', end_date: '2024-01-15' }))
      expect(result.description).toBeUndefined()
      expect(result.link).toBeUndefined()
    })
  })

  describe('propagates formatter failure for appointment with no dates', () => {
    it('throws when neither date nor datetime range is present', () => {
      expect(() => toAppointment(raw({}))).toThrow('Appointment has no start or end date')
    })

    it('throws with only a start_date', () => {
      expect(() => toAppointment(raw({ start_date: '2024-01-15' }))).toThrow(
        'Appointment has no start or end date',
      )
    })

    it('throws with only a start_date_time (asymmetric datetime input — no fallback pairing)', () => {
      expect(() =>
        toAppointment(raw({ start_date_time: toNaiveIso(2024, 1, 15, 14, 30) })),
      ).toThrow('Appointment has no start or end date')
    })
  })

  it('produces a full Appointment shape for a representative input', () => {
    const result: Appointment = toAppointment(
      raw({
        sort_index: 3,
        title: 'Pokalspiel',
        description: 'Austragung im heimischen Stadion',
        link: 'https://sve-eutingen.de/spiel',
        start_date_time: toNaiveIso(2024, 5, 11, 15, 0),
        end_date_time: toNaiveIso(2024, 5, 11, 16, 30),
      }),
    )
    expect(result).toEqual({
      date: 'Sat, 11. May 2024',
      time: '15:00 - 16:30 Uhr',
      title: 'Pokalspiel',
      description: 'Austragung im heimischen Stadion',
      link: 'https://sve-eutingen.de/spiel',
      startDateISO: toNaiveIso(2024, 5, 11, 15, 0),
      endDateISO: toNaiveIso(2024, 5, 11, 16, 30),
    })
  })
})

describe('bySortIndex', () => {
  const cases: Array<[RawAppointment, RawAppointment, number]> = [
    [raw({ sort_index: 1 }), raw({ sort_index: 2 }), -1],
    [raw({ sort_index: 2 }), raw({ sort_index: 1 }), 1],
    [raw({ sort_index: 5 }), raw({ sort_index: 5 }), 0],
    [raw({ sort_index: 0 }), raw({ sort_index: 10 }), -10],
    [raw({ sort_index: 10 }), raw({ sort_index: 0 }), 10],
    [raw({ sort_index: -3 }), raw({ sort_index: -1 }), -2],
    [raw({ sort_index: -1 }), raw({ sort_index: -3 }), 2],
  ]
  for (const [a, b, expected] of cases) {
    it(`sort_index ${a.sort_index} vs ${b.sort_index} -> ${expected}`, () => {
      expect(bySortIndex(a, b)).toBe(expected)
    })
  }

  it('sorts an array of raw appointments ascending by sort_index', () => {
    const items: RawAppointment[] = [
      raw({ sort_index: 3, title: 'c' }),
      raw({ sort_index: 1, title: 'a' }),
      raw({ sort_index: 2, title: 'b' }),
      raw({ sort_index: 0, title: 'root' }),
    ]
    expect([...items].sort(bySortIndex).map((i) => i.title)).toEqual(['root', 'a', 'b', 'c'])
  })

  it('is a stable comparator (equal sort_index returns 0)', () => {
    const a = raw({ sort_index: 7, title: 'a' })
    const b = raw({ sort_index: 7, title: 'b' })
    expect(bySortIndex(a, b)).toBe(0)
  })
})

import { describe, expect, it } from 'vitest'
import {
  AvailabilityState,
  availabilityState,
  calculateAvailabilityMessage,
  canSubscribe,
  convertToEventAvailability,
} from '@/api/events'
import type { RawEventCounter } from '@/types'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'

const counter = (fields: Partial<RawEventCounter>): RawEventCounter => ({
  id: 'evt-1',
  max_subscribers: 10,
  subscribers: 0,
  waiting_list: 0,
  max_waiting_list: 5,
  ...fields,
})

describe('convertToEventAvailability — producer sentinel + phase switch', () => {
  const cases: Array<{
    name: string
    input: RawEventCounter
    expectedSlots: number
    expectedWaitingList: boolean
    expectedState: AvailabilityState
    expectedMessage: string
  }> = [
    {
      name: 'Unlimited event (max_subscribers === -1): sentinel -1, subscriber phase',
      input: counter({ max_subscribers: -1, subscribers: 999 }),
      expectedSlots: -1,
      expectedWaitingList: false,
      expectedState: AvailabilityState.Unlimited,
      expectedMessage: 'Freie Plätze verfügbar',
    },
    {
      name: 'Subscribers open, many slots remaining',
      input: counter({ max_subscribers: 10, subscribers: 2 }),
      expectedSlots: 8,
      expectedWaitingList: false,
      expectedState: AvailabilityState.Subscribing,
      expectedMessage: 'Noch 8 freie Plätze',
    },
    {
      name: 'Subscribers open, exactly one slot remaining (singular message)',
      input: counter({ max_subscribers: 10, subscribers: 9 }),
      expectedSlots: 1,
      expectedWaitingList: false,
      expectedState: AvailabilityState.Subscribing,
      expectedMessage: 'Noch 1 freier Platz',
    },
    {
      name: 'Subscribers full, waiting-list open: phase switches, isWaitingList true',
      input: counter({
        max_subscribers: 10,
        subscribers: 10,
        max_waiting_list: 5,
        waiting_list: 1,
      }),
      expectedSlots: 4,
      expectedWaitingList: true,
      expectedState: AvailabilityState.WaitingList,
      expectedMessage: 'Warteliste ist geöffnet',
    },
    {
      name: 'Subscribers and waiting-list full: 0 + isWaitingList true (FullyBooked)',
      input: counter({
        max_subscribers: 10,
        subscribers: 10,
        max_waiting_list: 5,
        waiting_list: 5,
      }),
      expectedSlots: 0,
      expectedWaitingList: true,
      expectedState: AvailabilityState.FullyBooked,
      expectedMessage: 'Ausgebucht',
    },
    {
      name: 'Unlimited event ignores the waiting-list phase entirely',
      input: counter({
        max_subscribers: -1,
        subscribers: 999,
        max_waiting_list: 0,
        waiting_list: 0,
      }),
      expectedSlots: -1,
      expectedWaitingList: false,
      expectedState: AvailabilityState.Unlimited,
      expectedMessage: 'Freie Plätze verfügbar',
    },
    {
      name: 'Subscribers exactly at capacity but waiting-list open does NOT underflow below zero',
      input: counter({
        max_subscribers: 10,
        subscribers: 12,
        max_waiting_list: 3,
        waiting_list: 0,
      }),
      expectedSlots: 3,
      expectedWaitingList: true,
      expectedState: AvailabilityState.WaitingList,
      expectedMessage: 'Warteliste ist geöffnet',
    },
    {
      name: 'Negative phantom: subscribers exceed cap and waiting-list exceeds cap clamps to 0',
      input: counter({
        max_subscribers: 10,
        subscribers: 15,
        max_waiting_list: 4,
        waiting_list: 9,
      }),
      expectedSlots: 0,
      expectedWaitingList: true,
      expectedState: AvailabilityState.FullyBooked,
      expectedMessage: 'Ausgebucht',
    },
  ]

  for (const c of cases) {
    it(c.name, () => {
      const av = convertToEventAvailability(c.input)
      expect(av.availableSlots).toBe(c.expectedSlots)
      expect(av.isWaitingList).toBe(c.expectedWaitingList)
      expect(av.message).toBe(c.expectedMessage)
      expect(availabilityState(av)).toBe(c.expectedState)
    })
  }
})

describe('availabilityState — sentinel + phase decode (the one canonical read site)', () => {
  const cases: Array<{
    name: string
    slots: number
    waiting: boolean
    expected: AvailabilityState
  }> = [
    {
      name: 'sentinel -1 ⇒ Unlimited regardless of isWaitingList (well-formed input)',
      slots: -1,
      waiting: false,
      expected: AvailabilityState.Unlimited,
    },
    {
      name: 'subscriber phase, slots remaining ⇒ Subscribing',
      slots: 5,
      waiting: false,
      expected: AvailabilityState.Subscribing,
    },
    {
      name: 'subscriber phase, exactly one slot ⇒ Subscribing',
      slots: 1,
      waiting: false,
      expected: AvailabilityState.Subscribing,
    },
    {
      name: 'waiting-list phase, slots remaining ⇒ WaitingList',
      slots: 3,
      waiting: true,
      expected: AvailabilityState.WaitingList,
    },
    {
      name: 'waiting-list phase, exactly one slot ⇒ WaitingList',
      slots: 1,
      waiting: true,
      expected: AvailabilityState.WaitingList,
    },
    {
      name: 'waiting-list phase, zero slots ⇒ FullyBooked',
      slots: 0,
      waiting: true,
      expected: AvailabilityState.FullyBooked,
    },
    {
      name: 'subscriber phase, zero slots ⇒ FullyBooked (unreachable in producer but defensive)',
      slots: 0,
      waiting: false,
      expected: AvailabilityState.FullyBooked,
    },
  ]

  for (const c of cases) {
    it(c.name, () => {
      expect(availabilityState({ availableSlots: c.slots, isWaitingList: c.waiting })).toBe(
        c.expected,
      )
    })
  }
})

describe('calculateAvailabilityMessage — message derives through the state predicate', () => {
  const cases: Array<{ slots: number; waiting: boolean; expected: string }> = [
    { slots: -1, waiting: false, expected: 'Freie Plätze verfügbar' },
    { slots: 5, waiting: false, expected: 'Noch 5 freie Plätze' },
    { slots: 1, waiting: false, expected: 'Noch 1 freier Platz' },
    { slots: 3, waiting: true, expected: 'Warteliste ist geöffnet' },
    { slots: 1, waiting: true, expected: 'Warteliste ist geöffnet' },
    { slots: 0, waiting: true, expected: 'Ausgebucht' },
    { slots: 0, waiting: false, expected: 'Ausgebucht' },
  ]

  for (const { slots, waiting, expected } of cases) {
    it(`slots=${slots}, isWaitingList=${waiting} ⇒ "${expected}"`, () => {
      expect(calculateAvailabilityMessage({ availableSlots: slots, isWaitingList: waiting })).toBe(
        expected,
      )
    })
  }
})

describe('canSubscribe — "is booking open" predicate', () => {
  const cases: Array<{ name: string; slots: number; waiting: boolean; expected: boolean }> = [
    { name: 'Unlimited ⇒ true', slots: -1, waiting: false, expected: true },
    { name: 'Subscribing with many slots ⇒ true', slots: 5, waiting: false, expected: true },
    { name: 'Subscribing with one slot ⇒ true', slots: 1, waiting: false, expected: true },
    { name: 'WaitingList open ⇒ false', slots: 3, waiting: true, expected: false },
    { name: 'WaitingList with one slot ⇒ false', slots: 1, waiting: true, expected: false },
    { name: 'FullyBooked (waiting full) ⇒ false', slots: 0, waiting: true, expected: false },
    {
      name: 'FullyBooked (defensive, subscriber zero) ⇒ false',
      slots: 0,
      waiting: false,
      expected: false,
    },
  ]

  for (const { name, slots, waiting, expected } of cases) {
    it(name, () => {
      expect(canSubscribe({ availableSlots: slots, isWaitingList: waiting })).toBe(expected)
    })
  }
})

describe('-1 contract — the sentinel is pinned to exactly two sites', () => {
  const moduleSource = readFileSync(resolve(process.cwd(), 'src/api/events.ts'), 'utf8')

  it('Unlimited never produces a "Noch N" or "Ausgebucht" message', () => {
    expect(calculateAvailabilityMessage({ availableSlots: -1, isWaitingList: false })).toBe(
      'Freie Plätze verfügbar',
    )
    expect(calculateAvailabilityMessage({ availableSlots: -1, isWaitingList: true })).toBe(
      'Freie Plätze verfügbar',
    )
  })

  it('availabilityState reads === -1 (the canonical decode site)', () => {
    expect(availabilityState.toString()).toContain('=== -1')
  })

  it('calculateAvailabilityMessage never compares === -1 — it delegates to availabilityState', () => {
    const fnSource = extractFunctionSource(moduleSource, 'calculateAvailabilityMessage')
    expect(fnSource).not.toContain('=== -1')
  })

  it('canSubscribe never compares === -1 — it delegates to availabilityState', () => {
    const fnSource = extractFunctionSource(moduleSource, 'canSubscribe')
    expect(fnSource).not.toContain('=== -1')
  })
})

function extractFunctionSource(source: string, name: string): string {
  const start = source.indexOf(`function ${name}`)
  if (start === -1) throw new Error(`function ${name} not found in source`)
  let depth = 0
  let bodyStart = -1
  for (let i = start; i < source.length; i++) {
    if (source[i] === '{') {
      if (bodyStart === -1) bodyStart = i
      depth++
    } else if (source[i] === '}') {
      depth--
      if (depth === 0) return source.slice(start, i + 1)
    }
  }
  throw new Error(`unterminated function ${name}`)
}

