      sessionStorage.setItem('k', '{"v":1}')
      const v = sessionStorage.getItem('k')
      writeFileSync('/tmp/p.txt', `sessionStorage OK v=${v}\n`)
    } catch (e: any) {
      writeFileSync('/tmp/p.txt', `sessionStorage FAIL: ${e.message}\n`)
    }
    expect(true).toBe(true)
  })
})
