    expect(callback).toHaveBeenCalledTimes(2)
    expect(callback.mock.calls[0][0]).toEqual(seeded.data[EVENT_ID])
    expect(callback.mock.calls[1][0]).toEqual(expectedAvailabilityForFixture)
  })
})

